package com.nexuspc.catalog.product;
import com.nexuspc.catalog.dto.*; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.*;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductService service; public ProductController(ProductService s){service=s;}
 @GetMapping public Page<ProductResponse> search(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(defaultValue="false")boolean featured,@RequestParam(defaultValue="false")boolean bestseller,@RequestParam(name="new",defaultValue="false")boolean fresh,@RequestParam(required=false)BigDecimal minPrice,@RequestParam(required=false)BigDecimal maxPrice,@RequestParam(required=false)String brand,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt,desc")String sort){if(size<1||size>100)throw new IllegalArgumentException("size must be between 1 and 100");String[] s=sort.split(",");Sort sorting=Sort.by(s.length>1&&s[1].equalsIgnoreCase("asc")?Sort.Direction.ASC:Sort.Direction.DESC,s[0]);return service.search(q,category,featured,bestseller,fresh,minPrice,maxPrice,brand,PageRequest.of(Math.max(0,page),size,sorting));}
 @GetMapping("/featured") public Page<ProductResponse> featured(Pageable p){return service.search(null,null,true,false,false,null,null,null,p);} @GetMapping("/bestsellers") public Page<ProductResponse> bestsellers(Pageable p){return service.search(null,null,false,true,false,null,null,null,p);} @GetMapping("/new") public Page<ProductResponse> fresh(Pageable p){return service.search(null,null,false,false,true,null,null,null,p);} @GetMapping("/slug/{slug}") public ProductResponse slug(@PathVariable String slug){return service.get(slug);} @GetMapping("/{slug}") public ProductResponse get(@PathVariable String slug){return service.get(slug);}
 @PreAuthorize("hasAnyRole('ADMIN', 'SUPER_ADMIN')") @PostMapping public ProductResponse create(@Valid @RequestBody ProductRequest r){return service.create(r);} @PreAuthorize("hasAnyRole('ADMIN', 'SUPER_ADMIN')") @PutMapping("/{id}") public ProductResponse update(@PathVariable Long id,@Valid @RequestBody ProductRequest r){return service.update(id,r);} @PreAuthorize("hasAnyRole('ADMIN', 'SUPER_ADMIN')") @DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.delete(id);}}
